test_snippets.java:
public static void check(Solution solution) {
    assert Arrays.equals(solution.pyramidTransition("FFFA", new int[]{"FFF","FFA","FAF","AFF"}), True);
    assert Arrays.equals(solution.pyramidTransition("ABC", new int[]{"ABD","BDC","CDB","BDD","DEF","DEE"}), False);
    assert Arrays.equals(solution.pyramidTransition("ABC", new int[]{"ABD","BCE","DEF"}), True);
    assert Arrays.equals(solution.pyramidTransition("ABC", new int[]{"ABD","BCE","DEF","FFF","GHI"}), True);
    assert Arrays.equals(solution.pyramidTransition("CDC", new int[]{"ABA","ACA","BCD","BDA","CDE","CBD","DEC","DEF","FFF"}), False);
    assert Arrays.equals(solution.pyramidTransition("XXY", new int[]{"XXY","XYX","YXX","XYY","YYX","YYY"}), True);
    assert Arrays.equals(solution.pyramidTransition("BCD", new int[]{"BCC","CDE","CEA","FFF"}), True);
    assert Arrays.equals(solution.pyramidTransition("XXY", new int[]{"XYX","XYD","YXZ","XYZ","XZX","XYX","YZX","XYZ","XYZ"}), False);
    assert Arrays.equals(solution.pyramidTransition("BDD", new int[]{"ABB","ACB","BDC","BDB","BCC","BDD","CCC","BCB","CBC","DEC","CDB","DEB","CDE"}), False);
